import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T_str = next(iterator)
    except StopIteration:
        return

    T = int(T_str)

    results = []

    for _ in range(T):
        N = int(next(iterator))
        M = int(next(iterator))

        adj_destroyed = [set() for _ in range(N + 1)]

        for _ in range(M):
            u = int(next(iterator))
            v = int(next(iterator))
            adj_destroyed[u].add(v)
            adj_destroyed[v].add(u)

        if M == 0:
            if N == 2:
                results.append("2")
            else:
                results.append("0")
            continue

        if N == 2:
            if M == 1:
                results.append("2")
            else:
                results.appen("0")
            continue

        valid_X = []
        for i in range(1, N + 1):
            if len(adj_destroyed[i]) == 0:
                valid_X.append(i)

        if not valid_X:
            results.append("0")
            continue

        count = 0

        for x_node in valid_X:
            Y_set = set(range(1, N + 1))
            Y_set.discard(x_node)

            if not Y_set:
                continue

            valid_config = True
            for y_node in Y_set:
                if y_node in adj_destroyed[x_node]:
                    valid_config = False
                    break

            if valid_config:
                count += 1

        results.append(str(count))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
